import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import test from "node:test";
import { loadScript } from "./qml-script.mjs";

const Anim = loadScript(new URL("../Common/CompositorAnimations.js", import.meta.url));
const plain = value => JSON.parse(JSON.stringify(value));
const embedded = name => readFileSync(new URL(`../../core/internal/config/embedded/${name}`, import.meta.url), "utf8");

const NIRI_HEADER = `// ! DO NOT EDIT !
// ! AUTO-GENERATED BY DMS !
// ! CHANGES WILL BE OVERWRITTEN !
// ! PLACE YOUR CUSTOM CONFIGURATION ELSEWHERE !

`;

test("the shell's default animations match the files core deploys", () => {
    const Spec = loadScript(new URL("../Common/settings/SettingsSpec.js", import.meta.url));
    const defaults = {};
    for (const key of ["compositorAnimationPreset", "compositorAnimationSlowdown", "compositorAnimationOverrides"])
        defaults[key] = Spec.SPEC[key].def;
    const files = { niri: "niri-animations.kdl", hyprland: "hypr-animations.lua", mango: "mango-animations.conf" };
    for (const [compositor, name] of Object.entries(files)) {
        const core = embedded(name);
        assert.equal(Anim.generate(compositor, defaults), core, compositor);
        assert.equal(Anim.generate(compositor, {}), core, compositor);
        assert.equal(Anim.generate(compositor, { compositorAnimationPreset: "bogus" }), core, compositor);
    }
});

test("stock writes each compositor's upstream animations", () => {
    assert.equal(Anim.generate("niri", { compositorAnimationPreset: "stock" }), NIRI_HEADER + `animations {
    on
    slowdown 1.0
    workspace-switch {
        spring damping-ratio=1.0 stiffness=1000 epsilon=0.0001
    }
    window-open {
        duration-ms 150
        curve "ease-out-expo"
    }
    window-close {
        duration-ms 150
        curve "ease-out-quad"
    }
    horizontal-view-movement {
        spring damping-ratio=1.0 stiffness=800 epsilon=0.0001
    }
    window-movement {
        spring damping-ratio=1.0 stiffness=800 epsilon=0.0001
    }
    window-resize {
        spring damping-ratio=1.0 stiffness=800 epsilon=0.0001
    }
    config-notification-open-close {
        spring damping-ratio=0.6 stiffness=1000 epsilon=0.001
    }
    exit-confirmation-open-close {
        spring damping-ratio=0.6 stiffness=500 epsilon=0.01
    }
    screenshot-ui-open {
        duration-ms 200
        curve "ease-out-quad"
    }
    overview-open-close {
        spring damping-ratio=1.0 stiffness=800 epsilon=0.0001
    }
    recent-windows-close {
        spring damping-ratio=1.0 stiffness=800 epsilon=0.001
    }
}
`);

    assert.equal(Anim.generate("mango", { compositorAnimationPreset: "stock" }), `# Auto-generated by DMS - do not edit manually
animations=1
layer_animations=1
animation_type_open=slide
animation_type_close=slide
animation_fade_in=1
animation_fade_out=1
tag_animation_direction=1
zoom_initial_ratio=0.4
zoom_end_ratio=0.8
fade_in_begin_opacity=0.5
fade_out_begin_opacity=0.8
animation_duration_move=500
animation_duration_open=400
animation_duration_tag=350
animation_duration_close=800
animation_duration_focus=0
animation_curve_open=0.46,1,0.29,1
animation_curve_move=0.46,1,0.29,1
animation_curve_tag=0.46,1,0.29,1
animation_curve_close=0.08,0.92,0,1
animation_curve_focus=0.46,1,0.29,1
animation_curve_opacity_fade_out=0.5,0.5,0.5,0.5
animation_curve_opacity_fade_in=0.46,1,0.29,1
`);

    const hypr = Anim.generate("hyprland", { compositorAnimationPreset: "stock" });
    const lines = hypr.split("\n");
    assert.ok(lines.includes(`hl.curve("dms_easy", { type = "spring", mass = 1, stiffness = 238.1191, dampening = 24.2128 })`));
    assert.ok(lines.includes(`hl.animation({ leaf = "windowsIn", enabled = true, speed = 4.1, spring = "dms_easy", style = "popin 87%" })`));
    assert.ok(lines.includes(`hl.animation({ leaf = "specialWorkspaceOut", enabled = true, speed = 1.94, bezier = "dms_almostLinear", style = "fade" })`));
    assert.equal(lines.filter(line => line.startsWith("hl.animation(")).length, 32);
    assert.doesNotMatch(hypr, /"default"|"linear"/);
});

test("the fragment overrides an earlier global switch and the gradient loops", () => {
    for (const preset of Anim.PRESETS) {
        assert.ok(Anim.generate("niri", { compositorAnimationPreset: preset }).includes("animations {\n    on\n    slowdown 1.0\n"), preset);

        const hypr = Anim.generate("hyprland", { compositorAnimationPreset: preset, compositorAnimationSlowdown: 3.0 });
        assert.ok(hypr.includes("\nhl.config({ animations = { enabled = true } })\n"), preset);
        assert.ok(hypr.endsWith(`hl.animation({ leaf = "borderangle", enabled = false })
local minor = tonumber(hl.version():match("^0%.(%d+)"))
if not minor or minor >= 56 then
    hl.animation({ leaf = "shadowangle", enabled = false })
    hl.animation({ leaf = "glowangle", enabled = false })
end
`), preset);
    }
});

test("conversions follow the pinned spring and overshoot tables", () => {
    assert.deepEqual([500, 150, 470, 430, 320, 350].map(Anim.stiffnessFor), [380, 4225, 430, 514, 928, 776]);
    const y1 = [0, 5, 10, 15, 20, 25, 30, 35, 40, 45, 50].map(b => Anim.bounceCurve(b)[1]);
    assert.deepEqual(y1, [1, 1.03, 1.08, 1.15, 1.22, 1.29, 1.37, 1.46, 1.55, 1.65, 1.76]);
});

test("overrides bounce spatial nodes only and keep fades flat", () => {
    const niri = Anim.generate("niri", { compositorAnimationPreset: "stock", compositorAnimationOverrides: { open: { duration: 150, bounce: 30 }, popups: { duration: 500, bounce: 50 } } });
    const node = name => niri.match(new RegExp(`    ${name} \\{\\n        (.*)\\n`))[1];
    assert.equal(node("window-open"), "spring damping-ratio=0.7 stiffness=4225 epsilon=0.0001");
    assert.equal(node("window-close"), "spring damping-ratio=1.0 stiffness=4225 epsilon=0.0001");
    assert.equal(node("exit-confirmation-open-close"), "spring damping-ratio=0.5 stiffness=380 epsilon=0.01");
    assert.equal(node("screenshot-ui-open"), "spring damping-ratio=1.0 stiffness=380 epsilon=0.001");
    assert.equal(node("workspace-switch"), "spring damping-ratio=1.0 stiffness=1000 epsilon=0.0001");

    const hypr = Anim.generate("hyprland", { compositorAnimationPreset: "stock", compositorAnimationOverrides: { open: { duration: 200, bounce: 50 } } }).split("\n");
    assert.ok(hypr.includes(`hl.curve("dms_open", { type = "bezier", points = { { 0.38, 1.76 }, { 0.22, 1 } } })`));
    assert.ok(hypr.includes(`hl.animation({ leaf = "windowsIn", enabled = true, speed = 2, bezier = "dms_open", style = "popin 87%" })`));
    assert.ok(hypr.includes(`hl.animation({ leaf = "windowsOut", enabled = true, speed = 1, bezier = "dms_fade", style = "popin 87%" })`));
    assert.ok(hypr.includes(`hl.animation({ leaf = "fadeIn", enabled = true, speed = 1, bezier = "dms_fade" })`));
    assert.ok(hypr.includes(`hl.animation({ leaf = "windowsMove", enabled = true, speed = 4.79, spring = "dms_easy" })`));

    const fadeStyled = Anim.generate("hyprland", { compositorAnimationPreset: "stock", compositorAnimationOverrides: { workspace: { duration: 190, bounce: 25 }, popups: { duration: 400, bounce: 25 } } })
        .split("\n").filter(line => line.includes(`style = "fade"`));
    assert.equal(fadeStyled.length, 8);
    for (const line of fadeStyled)
        assert.match(line, /bezier = "dms_fade"/);

    const bounceOnly = { compositorAnimationPreset: "material", compositorAnimationOverrides: Anim.setOverride("hyprland", "material", {}, "open", "bounce", 25) };
    const material = Anim.generate("hyprland", bounceOnly).split("\n");
    assert.ok(material.includes(`hl.animation({ leaf = "windowsIn", enabled = true, speed = 5, bezier = "dms_open", style = "popin 80%" })`));
    assert.ok(material.includes(`hl.animation({ leaf = "windowsOut", enabled = true, speed = 2, bezier = "dms_fade", style = "popin 80%" })`));
    assert.ok(material.includes(`hl.animation({ leaf = "fadeOut", enabled = true, speed = 1.5, bezier = "dms_fade" })`));
    assert.match(Anim.generate("mango", bounceOnly), /\nanimation_duration_open=500\n(.*\n)*animation_duration_close=200\n/);

    const mango = Anim.generate("mango", { compositorAnimationOverrides: { open: { duration: 300, bounce: 20 }, popups: { duration: 900, bounce: 50 } } });
    assert.match(mango, /\nanimation_duration_open=300\n/);
    assert.match(mango, /\nanimation_duration_close=300\n/);
    assert.match(mango, /\nanimation_curve_open=0.38,1.22,0.22,1\n/);
    assert.match(mango, /\nanimation_curve_opacity_fade_in=0.34,0.8,0.34,1\n/);
});

test("global speed scales every compositor", () => {
    assert.ok(Anim.generate("niri", { compositorAnimationSlowdown: 1.5 }).startsWith(NIRI_HEADER + "animations {\n    on\n    slowdown 1.5\n    workspace-switch {\n"));

    const hypr = Anim.generate("hyprland", { compositorAnimationPreset: "stock", compositorAnimationSlowdown: 3.0 }).split("\n");
    assert.ok(hypr.includes(`hl.curve("dms_easy", { type = "spring", mass = 1, stiffness = 26.4577, dampening = 8.0709 })`));
    assert.ok(hypr.includes(`hl.animation({ leaf = "windowsOut", enabled = true, speed = 4.47, bezier = "dms_linear", style = "popin 87%" })`));

    const mango = Anim.generate("mango", { compositorAnimationSlowdown: 1.5 });
    assert.match(mango, /\nanimation_duration_move=705\n/);
    assert.match(mango, /\nanimation_duration_open=225\n/);
    assert.match(mango, /\nanimation_duration_focus=0\n/);
});

test("overrides are per group on top of the preset's representative values", () => {
    const base = plain(Anim.effective("hyprland", "stock", {}));
    assert.deepEqual(base.workspace, { duration: 190, bounce: 0, overridden: false });

    const before = {};
    const after = Anim.setOverride("niri", "material", before, "movement", "bounce", 35);
    assert.notEqual(after, before);
    assert.deepEqual(before, {});
    assert.deepEqual(plain(after), { movement: { duration: 500, bounce: 35 } });
    assert.deepEqual(plain(Anim.effective("niri", "material", after).movement), { duration: 500, bounce: 35, overridden: true });
    assert.deepEqual(plain(Anim.effective("niri", "dms", { open: { duration: 5000 } }).open), { duration: 1000, bounce: 0, overridden: true });

    assert.equal(Anim.isCustom("niri", after), true);
    assert.equal(Anim.isCustom("niri", Anim.clearOverride(after, "movement")), false);
    assert.equal(Anim.isCustom("mango", { popups: { duration: 300, bounce: 10 } }), false);
    assert.equal(Anim.isCustom("niri", { popups: { duration: 300, bounce: 10 } }), true);
});

test("only controls that change the written config are offered", () => {
    for (const compositor of Anim.COMPOSITORS) {
        for (const preset of Anim.PRESETS) {
            const live = plain(Anim.controls(compositor, preset));
            assert.deepEqual(Object.keys(live), plain(Anim.groups(compositor)), `${compositor} ${preset}`);
            for (const [group, c] of Object.entries(live)) {
                const fadeOnly = compositor === "hyprland" && preset === "stock" && (group === "workspace" || group === "popups");
                assert.deepEqual(c, { duration: true, bounce: !fadeOnly }, `${compositor} ${preset} ${group}`);
            }
        }
    }
});

test("group durations never leave the slider range", () => {
    const durations = (compositor, settings) => Anim.generate(compositor, settings).split("\n")
        .map(line => compositor === "mango" ? line.match(/^animation_duration_(?!focus)\w+=(\d+)$/)?.[1] : line.match(/speed = ([\d.]+)/)?.[1] * 100)
        .filter(v => v !== undefined && !Number.isNaN(Number(v))).map(Number);
    for (const compositor of ["hyprland", "mango"]) {
        for (const preset of Anim.PRESETS) {
            for (const duration of [Anim.DURATION_MIN, Anim.DURATION_MAX]) {
                const overrides = {};
                for (const group of Anim.groups(compositor))
                    overrides[group] = { duration: duration, bounce: 0 };
                for (const ms of durations(compositor, { compositorAnimationPreset: preset, compositorAnimationOverrides: overrides }))
                    assert.ok(ms >= Anim.DURATION_MIN && ms <= Anim.DURATION_MAX, `${compositor} ${preset} ${duration}: ${ms}`);
            }
        }
    }
});
